// Get data from previous nodes
const testInfo = $('Get Test Info').first().json;
const questionsData = $('Get Questions').all();
const answersData = $('Get Answers').all();

// Group answers by question ID
const answersByQuestion = {};
for (const answerItem of answersData) {
  const qid = answerItem.json.questionid;
  if (!answersByQuestion[qid]) {
    answersByQuestion[qid] = [];
  }
  answersByQuestion[qid].push({
    letter: answerItem.json.answer,
    text: answerItem.json.answertext,
    is_correct: answerItem.json.iscorrect === 1
  });
}

// Build questions array with answers
const questions = questionsData.map(qItem => {
  const q = qItem.json;
  return {
    id: q.id,
    name: q.name,
    type: q.type,
    points: q.points,
    qorder: q.qorder,
    html: q.html,
    answers: answersByQuestion[q.id] || []
  };
});

// Sort by question order
questions.sort((a, b) => a.qorder - b.qorder);

// Return complete test data
return [{
  json: {
    test_id: testInfo.id,
    test_name: testInfo.name,
    grade: testInfo.testgrade,
    subject: testInfo.subject_name,
    questions: questions,
    total_questions: questions.length
  }
}];
